rain the generated value. It can subtly guide the model by clarifying the intent of a\n   * field.\n   */\n  title?: string;\n  /** Optional. The items of the property. */\n  items?: T;\n  /** The minimum number of items (elements) in a schema of {@link (SchemaType:type)} `array`. */\n  minItems?: number;\n  /** The maximum number of items (elements) in a schema of {@link (SchemaType:type)} `array`. */\n  maxItems?: number;\n  /** Optional. Map of `Schema` objects. */\n  properties?: {\n    [k: string]: T;\n  };\n  /** A hint suggesting the order in which the keys should appear in the generated JSON string. */\n  propertyOrdering?: string[];\n  /** Optional. The enum of the property. */\n  enum?: string[];\n  /** Optional. The example of the property. */\n  example?: unknown;\n  /** Optional. Whether the property is nullable. */\n  nullable?: boolean;\n  /** The minimum value of a numeric type. */\n  minimum?: number;\n  /** The maximum value of a numeric type. */\n  maximum?: number;\n  [key: string]: unknown;\n}\n\n/**\n * Params passed to {@link Schema} static methods to create specific\n * {@link Schema} classes.\n * @public\n */\nexport interface SchemaParams extends SchemaShared<SchemaInterface> {}\n\n/**\n * Final format for {@link Schema} params passed to backend requests.\n * @public\n */\nexport interface SchemaRequest extends SchemaShared<SchemaRequest> {\n  /**\n   * The type of the property. this can only be undefined when using `anyOf` schemas,\n   * which do not have an explicit type in the {@link https://swagger.io/docs/specification/v3_0/data-models/data-types/#any-type | OpenAPI specification }.\n   */\n  type?: SchemaType;\n  /** Optional. Array of required property. */\n  required?: string[];\n}\n\n/**\n * Interface for {@link Schema} class.\n * @public\n */\nexport interface SchemaInterface extends SchemaShared<SchemaInterface> {\n  /**\n   * The type of the property. this can only be undefined when using `anyof` schemas,\n   * which do not have an explicit type in the {@link https://swagger.io/docs/specification/v3_0/data-models/data-types/#any-type | OpenAPI Specification}.\n   */\n  type?: SchemaType;\n}\n\n/**\n * Interface for JSON parameters in a schema of {@link (SchemaType:type)}\n * \"object\" when not using the `Schema.object()` helper.\n * @public\n */\nexport interface ObjectSchemaRequest extends SchemaRequest {\n  type: 'object';\n  /**\n   * This is not a property accepted in the final request to the backend, but is\n   * a client-side convenience property that is only usable by constructing\n   * a schema through the `Schema.object()` helper method. Populating this\n   * property will cause response errors if the object is not wrapped with\n   * `Schema.object()`.\n   */\n  optionalProperties?: never;\n}\n","/**\n * @license\n * Copyright 2024 Google LLC\n *\n * Licensed under the Apache License, Version 2.0 (the \"License\");\n * you may not use this file except in compliance with the License.\n * You may obtain a copy of the License at\n *\n *   http://www.apache.org/licenses/LICENSE-2.0\n *\n * Unless required by applicable law or agreed to in writing, software\n * distributed under the License is distributed on an \"AS IS\" BASIS,\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n * See the License for the specific language governing permissions and\n * limitations under the License.\n */\n\nimport { FirebaseApp } from '@firebase/app';\nimport { Backend } from './backend';\nimport {\n  Content,\n  GenerateContentResult,\n  GenerateContentStreamResult,\n  Part,\n  RequestOptions,\n  SingleRequestOptions,\n  StartTemplateChatParams\n} from './types';\n\nexport * from './types';\n\n/**\n * An instance of the Firebase AI SDK.\n *\n * Do not create this instance directly. Instead, use {@link getAI | getAI()}.\n *\n * @public\n */\nexport interface AI {\n  /**\n   * The {@link @firebase/app#FirebaseApp} this {@link AI} instance is associated with.\n   */\n  app: FirebaseApp;\n  /**\n   * A {@link Backend} instance that specifies the configuration for the target backend,\n   * either the Gemini Developer API (using {@link GoogleAIBackend}) or the\n   * Agent Platform Gemini API (using {@link AgentPlatformBackend}).\n   */\n  backend: Backend;\n  /**\n   * Options applied to this {@link AI} instance.\n   */\n  options?: AIOptions;\n  /**\n   * @deprecated use `AI.backend.location` instead.\n   *\n   * The location configured for this AI service instance, relevant for\n   * Agent Platform Gemini API backends.\n   */\n  location: string;\n}\n\n/**\n * An enum-like object containing constants that represent the supported backends\n * for the Firebase AI SDK.\n * This determines which backend service (Gemini Developer API or Agent Platform Gemini API)\n * the SDK will communicate with.\n *\n * These values are assigned to the `backendType` property within the specific backend\n * configuration objects ({@link GoogleAIBackend} or {@link AgentPlatformBackend}) to identify\n * which service to target.\n *\n * @public\n */\nexport const BackendType = {\n  /**\n   * Identifies the backend service for the Agent Platform Gemini API provided through Google Cloud.\n   * Use this constant when creating a {@link AgentPlatformBackend} configuration.\n   */\n  AGENT_PLATFORM: 'AGENT_PLATFORM',\n\n  /**\n   * Identifies the backend service for the Agent Platform Gemini API\n   * (formerly known as Vertex AI Gemini API) provided through Google Cloud.\n   * Use this constant when creating a {@link VertexAIBackend} configuration.\n   * @deprecated - Use {@link AgentPlatformBackend} instead.\n   */\n  VERTEX_AI: 'VERTEX_AI',\n\n  /**\n   * Identifies the backend service for the Gemini Developer API ({@link https://ai.google/ | Google AI}).\n   * Use this constant when creating a {@link GoogleAIBackend} configuration.\n   */\n  GOOGLE_AI: 'GOOGLE_AI'\n} as const; // Using 'as const' makes the string values literal types\n\n/**\n * Type alias representing valid backend types.\n * It should be either `'AGENT_PLATFORM'` or `'GOOGLE_AI'` (`'VERTEX_AI'` is deprecated).\n *\n * @public\n */\nexport type BackendType = (typeof BackendType)[keyof typeof BackendType];\n\n/**\n * Options for initializing the AI service using {@link getAI | getAI()}.\n * This allows specifying which backend to use (Gemini Developer API or Agent Platform Gemini API)\n * and configuring its specific options (like location for Agent Platform).\n *\n * @public\n */\nexport interface AIOptions {\n  /**\n   * The backend configuration to use for the AI service instance.\n   * Defaults to the Gemini Developer API backend ({@link GoogleAIBackend}).\n   */\n  backend?: Backend;\n  /**\n   * Whether to use App Check limited use tokens. Defaults to false.\n   */\n  useLimitedUseAppCheckTokens?: boolean;\n}\n\n/**\n * Interface representing a `ChatSession` class for use with server\n * prompt templates that enables sending chat messages and stores\n * history of sent and received messages so far.\n *\n * @beta\n */\nexport interface TemplateChatSession {\n  params: StartTemplateChatParams;\n  requestOptions?: RequestOptions;\n  /**\n   * Sends a chat message and receives a non-streaming\n   * {@link GenerateContentResult}\n   */\n  sendMessage(\n    request: string | Array<string | Part>,\n    singleRequestOptions?: SingleRequestOptions\n  ): Promise<GenerateContentResult>;\n  /**\n   * Sends a chat message and receives the response as a\n   * {@link GenerateContentStreamResult} containing an iterable stream\n   * and a response promise.\n   */\n  sendMessageStream(\n    request: string | Array<string | Part>,\n    singleRequestOptions?: SingleRequestOptions\n  ): Promise<GenerateContentStreamResult>;\n  /**\n   * Gets the chat history so far. Blocked prompts are not added to history.\n   * Neither blocked candidates nor the prompts that generated them are added\n   * to history.\n   */\n  getHistory(): Promise<Content[]>;\n}\n","/**\n * @license\n * Copyright 2025 Google LLC\n *\n * Licensed under the Apache License, Version 2.0 (the \"License\");\n * you may not use this file except in compliance with the License.\n * You may obtain a copy of the License at\n *\n *   http://www.apache.org/licenses/LICENSE-2.0\n *\n * Unless required by applicable law or agreed to in writing, software\n * distributed under the License is distributed on an \"AS IS\" BASIS,\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n * See the License for the specific language governing permissions and\n * limitations under the License.\n */\n\nimport {\n  DEFAULT_API_VERSION,\n  DEFAULT_LOCATION,\n  LEGACY_DEFAULT_LOCATION\n} from './constants';\nimport { BackendType } from './public-types';\n\n/**\n * Abstract base class representing the configuration for an AI service backend.\n * This class should not be instantiated directly. Use its subclasses; {@link GoogleAIBackend} for\n * the Gemini Developer API (via {@link https://ai.google/ | Google AI}) and {@link AgentPlatformBackend}\n * for the Agent Platform Gemini API.\n *\n * @public\n */\nexport abstract class Backend {\n  /**\n   * Specifies the backend type.\n   */\n  readonly backendType: BackendType;\n\n  /**\n   * Protected constructor for use by subclasses.\n   * @param type - The backend type.\n   */\n  protected constructor(type: BackendType) {\n    this.backendType = type;\n  }\n\n  /**\n   * @internal\n   */\n  abstract _getModelPath(project: string, model: string): string;\n\n  /**\n   * @internal\n   */\n  abstract _getTemplatePath(project: string, templateId: string): string;\n}\n\n/**\n * Configuration class for the Gemini Developer API.\n *\n * Use this with {@link AIOptions} when initializing the AI service via\n * {@link getAI | getAI()} to specify the Gemini Developer API as the backend.\n *\n * @public\n */\nexport class GoogleAIBackend extends Backend {\n  /**\n   * Creates a configuration object for the Gemini Developer API backend.\n   */\n  constructor() {\n    super(BackendType.GOOGLE_AI);\n  }\n\n  /**\n   * @internal\n   */\n  _getModelPath(project: string, model: string): string {\n    return `/${DEFAULT_API_VERSION}/projects/${project}/${model}`;\n  }\n\n  /**\n   * @internal\n   */\n  _getTemplatePath(project: string, templateId: string): string {\n    return `/${DEFAULT_API_VERSION}/projects/${project}/templates/${templateId}`;\n  }\n}\n\n/**\n * Configuration class for the Agent Platform Gemini API (formerly known as the\n * Vertex AI Gemini API).\n *\n * Use this with {@link AIOptions} when initializing the AI service via\n * {@link getAI | getAI()} to specify the Agent Platform Gemini API as the backend.\n *\n * @deprecated - Use {@link AgentPlatformBackend} instead.\n *\n * @public\n */\nexport class VertexAIBackend extends Backend {\n  /**\n   * The region identifier.\n   * See {@link https://firebase.google.com/docs/ai-logic/locations?api=vertex#available-locations | Agent Platform Gemini API locations}\n   * for a list of supported locations.\n   */\n  readonly location: string = LEGACY_DEFAULT_LOCATION;\n\n  /**\n   * Creates a configuration object for the Agent Platform Gemini API (formerly\n   * known as the Vertex AI Gemini API) backend.\n   *\n   * @param location - The region identifier, defaulting to `us-central1`;\n   * see {@link https://firebase.google.com/docs/ai-logic/locations?api=vertex#available-locations | Agent Platform Gemini API locations}\n   * for a list of supported locations.\n   */\n  constructor(location?: string) {\n    super(BackendType.VERTEX_AI);\n    if (location) {\n      this.location = location;\n    }\n  }\n\n  /**\n   * @internal\n   */\n  _getModelPath(project: string, model: string): string {\n    return `/${DEFAULT_API_VERSION}/projects/${project}/locations/${this.location}/${model}`;\n  }\n\n  /**\n   * @internal\n   */\n  _getTemplatePath(project: string, templateId: string): string {\n    return `/${DEFAULT_API_VERSION}/projects/${project}/locations/${this.location}/templates/${templateId}`;\n  }\n}\n\n/**\n * Configuration class for the Agent Platform Gemini API.\n *\n * Use this with {@link AIOptions} when initializing the AI service via\n * {@link getAI | getAI()} to specify the Agent Platform Gemini API as the backend.\n *\n * @public\n */\nexport class AgentPlatformBackend extends Backend {\n  /**\n   * The region identifier.\n   * See {@link https://firebase.google.com/docs/ai-logic/locations?api=vertex#available-locations | Agent Platform locations}\n   * for a list of supported locations.\n   */\n  readonly location: string = DEFAULT_LOCATION;\n\n  /**\n   * Creates a configuration object for the Agent Platform backend.\n   *\n   * @param location - The region identifier, defaulting to `global`;\n   * see {@link https://firebase.google.com/docs/ai-logic/locations?api=vertex#available-locations | Agent Platform locations}\n   * for a list of supported locations.\n   */\n  constructor(location?: string) {\n    super(BackendType.AGENT_PLATFORM);\n    if (location) {\n      this.location = location;\n    }\n  }\n\n  /**\n   * @internal\n   */\n  _getModelPath(project: string, model: string): string {\n    return `/${DEFAULT_API_VERSION}/projects/${project}/locations/${this.location}/${model}`;\n  }\n\n  /**\n   * @internal\n   */\n  _getTemplatePath(project: string, templateId: string): string {\n    return `/${DEFAULT_API_VERSION}/projects/${project}/locations/${this.location}/templates/${templateId}`;\n  }\n}\n","/**\n * @license\n * Copyright 2025 Google LLC\n *\n * Licensed under the Apache License, Version 2.0 (the \"License\");\n * you may not use this file except in compliance with the License.\n * You may obtain a copy of the License at\n *\n *   http://www.apache.org/licenses/LICENSE-2.0\n *\n * Unless required by applicable law or agreed to in writing, software\n * distributed under the License is distributed on an \"AS IS\" BASIS,\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n * See the License for the specific language governing permissions and\n * limitations under the License.\n */\n\nimport { AI_TYPE } from './constants';\nimport { AIError } from './errors';\nimport { AIErrorCode } from './types';\nimport {\n  AgentPlatformBackend,\n  Backend,\n  GoogleAIBackend,\n  VertexAIBackend\n} from './backend';\n\n/**\n * Encodes a {@link Backend} into a string that will be used to uniquely identify {@link AI}\n * instances by backend type.\n *\n * @internal\n */\nexport function encodeInstanceIdentifier(backend: Backend): string {\n  if (backend instanceof GoogleAIBackend) {\n    return `${AI_TYPE}/googleai`;\n  } else if (backend instanceof VertexAIBackend) {\n    return `${AI_TYPE}/vertexai/${backend.location}`;\n  } else if (backend instanceof AgentPlatformBackend) {\n    return `${AI_TYPE}/agentplatform/${backend.location}`;\n  } else {\n    throw new AIError(\n      AIErrorCode.ERROR,\n      `Invalid backend: ${JSON.stringify(backend.backendType)}`\n    );\n  }\n}\n\n/**\n * Decodes an instance identifier string into a {@link Backend}.\n *\n * @internal\n */\nexport function decodeInstanceIdentifier(instanceIdentifier: string): Backend {\n  const identifierParts = instanceIdentifier.split('/');\n  if (identifierParts[0] !== AI_TYPE) {\n    throw new AIError(\n      AIErrorCode.ERROR,\n      `Invalid instance identifier, unknown prefix '${identifierParts[0]}'`\n    );\n  }\n  const backendType = identifierParts[1];\n  switch (backendType) {\n    case 'vertexai':\n      const vertexLocation: string | undefined = identifierParts[2];\n      if (!vertexLocation) {\n        throw new AIError(\n          AIErrorCode.ERROR,\n          `Invalid instance identifier, unknown location '${instanceIdentifier}'`\n        );\n      }\n      return new VertexAIBackend(vertexLocation);\n    case 'agentplatform':\n      const location: string | undefined = identifierParts[2];\n      if (!location) {\n        throw new AIError(\n          AIErrorCode.ERROR,\n          `Invalid instance identifier, unknown location '${instanceIdentifier}'`\n        );\n      }\n      return new AgentPlatformBackend(location);\n    case 'googleai':\n      return new GoogleAIBackend();\n    default:\n      throw new AIError(\n        AIErrorCode.ERROR,\n        `Invalid instance identifier string: '${instanceIdentifier}'`\n      );\n  }\n}\n","/**\n * @license\n * Copyright 2024 Google LLC\n *\n * Licensed under the Apache License, Version 2.0 (the \"License\");\n * you may not use this file except in compliance with the License.\n * You may obtain a copy of the License at\n *\n *   http://www.apache.org/licenses/LICENSE-2.0\n *\n * Unless required by applicable law or agreed to in writing, software\n * distributed under the License is distributed on an \"AS IS\" BASIS,\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n * See the License for the specific language governing permissions and\n * limitations under the License.\n */\n\nimport { Logger } from '@firebase/logger';\n\nexport const logger = new Logger('@firebase/vertexai');\n","/**\n * @license\n * Copyright 2025 Google LLC\n *\n * Licensed under the Apache License, Version 2.0 (the \"License\");\n * you may not use this file except in compliance with the License.\n * You may obtain a copy of the License at\n *\n *   http://www.apache.org/licenses/LICENSE-2.0\n *\n * Unless required by applicable law or agreed to in writing, software\n * distributed under the License is distributed on an \"AS IS\" BASIS,\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n * See the License for the specific language governing permissions and\n * limitations under the License.\n */\n/**\n * The subset of the Prompt API\n * (see {@link https://github.com/webmachinelearning/prompt-api#full-api-surface-in-web-idl }\n * required for hybrid functionality.\n *\n * @internal\n */\nexport interface LanguageModel extends EventTarget {\n  create(options?: LanguageModelCreateOptions): Promise<LanguageModel>;\n  availability(options?: LanguageModelCreateCoreOptions): Promise<Availability>;\n  prompt(\n    input: LanguageModelPrompt,\n    options?: LanguageModelPromptOptions\n  ): Promise<string>;\n  promptStreaming(\n    input: LanguageModelPrompt,\n    options?: LanguageModelPromptOptions\n  ): ReadableStream;\n  measureInputUsage(\n    input: LanguageModelPrompt,\n    options?: LanguageModelPromptOptions\n  ): Promise<number>;\n  destroy(): undefined;\n}\n\n/**\n * @internal\n */\nexport enum Availability {\n  'UNAVAILABLE' = 'unavailable',\n  'DOWNLOADABLE' = 'downloadable',\n  'DOWNLOADING' = 'downloading',\n  'AVAILABLE' = 'available'\n}\n\n/**\n * Configures the creation of an on-device language model session.\n * @public\n */\nexport interface LanguageModelCreateCoreOptions {\n  /**\n   * @deprecated\n   */\n  topK?: number;\n  /**\n   * @deprecated\n   */\n  temperature?: number;\n  /**\n   * Defaults to image input and English text input\n   * if not overriden.\n   */\n  expectedInputs?: LanguageModelExpected[];\n  /**\n   * Defaults to English text output if not overriden.\n   */\n  expectedOutputs?: LanguageModelExpected[];\n  /**\n   * The native download monitor provided by the Chrome API.\n   * This provides direct access to the monitor object and is\n   * only needed for advanced cases. For\n   * a simpler download monitoring interface, provide an\n   * `onDownloadProgress` callback\n   * to {@link GenerativeModel.initializeDeviceModel} instead.\n   */\n  monitor?: (monitor: LanguageModelDownloadMonitor) => void;\n}\n\n/**\n * Interface representing the Chrome Prompt API's native\n * download monitor object.\n * @public\n */\nexport interface LanguageModelDownloadMonitor {\n  addEventListener: (\n    eventType: 'downloadprogress',\n    eventListener: (e: { loaded: number }) => void\n  ) => void;\n  removeEventListener: (\n    eventType: 'downloadprogress',\n    eventListener: (e: { loaded: number }) => void\n  ) => void;\n}\n\n/**\n * Configures the creation of an on-device language model session.\n * @public\n */\nexport interface LanguageModelCreateOptions extends LanguageModelCreateCoreOptions {\n  signal?: AbortSignal;\n  initialPrompts?: LanguageModelMessage[];\n}\n\n/**\n * Options for an on-device language model prompt.\n * @public\n */\nexport interface LanguageModelPromptOptions {\n  responseConstraint?: object;\n  // TODO: Restore AbortSignal once the API is defined.\n}\n\n/**\n * Options for the expected inputs for an on-device language model.\n * @public\n */ export interface LanguageModelExpected {\n  type: LanguageModelMessageType;\n  languages?: string[];\n}\n\n/**\n * An on-device language model prompt.\n * @public\n */\nexport type LanguageModelPrompt = LanguageModelMessage[];\n\n/**\n * An on-device language model message.\n * @public\n */\nexport interface LanguageModelMessage {\n  role: LanguageModelMessageRole;\n  content: LanguageModelMessageContent[];\n}\n\n/**\n * An on-device language model content object.\n * @public\n */\nexport interface LanguageModelMessageContent {\n  type: LanguageModelMessageType;\n  value: LanguageModelMessageContentValue;\n}\n\n/**\n * Allowable roles for on-device language model usage.\n * @public\n */\nexport type LanguageModelMessageRole = 'system' | 'user' | 'assistant';\n\n/**\n * Allowable types for on-device language model messages.\n * @public\n */\nexport type LanguageModelMessageType = 'text' | 'image' | 'audio';\n\n/**\n * Content formats that can be provided as on-device message content.\n * @public\n */\nexport type LanguageModelMessageContentValue =\n  ImageBitmapSource | AudioBuffer | BufferSource | string;\n","/**\n * @license\n * Copyright 2025 Google LLC\n *\n * Licensed under the Apache License, Version 2.0 (the \"License\");\n * you may not use this file except in compliance with the License.\n * You may obtain a copy of the License at\n *\n *   http://www.apache.org/licenses/LICENSE-2.0\n *\n * Unless required by applicable law or agreed to in writing, software\n * distributed under the License is distributed on an \"AS IS\" BASIS,\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n * See the License for the specific language governing permissions and\n * limitations under the License.\n */\n\nimport { getGlobal } from '@firebase/util';\nimport { AIError } from '../errors';\nimport { logger } from '../logger';\nimport {\n  CountTokensRequest,\n  GenerateContentRequest,\n  InferenceMode,\n  Part,\n  AIErrorCode,\n  OnDeviceParams,\n  Content,\n  Role\n} from '../types';\nimport { ChromeAdapter } from '../types/chrome-adapter';\nimport {\n  Availability,\n  LanguageModel,\n  LanguageModelExpected,\n  LanguageModelMessage,\n  LanguageModelMessageContent,\n  LanguageModelMessageRole\n} from '../types/language-model';\n\n// Defaults to English text. This can be overriden by user config.\nconst defaultExpectedText: LanguageModelExpected = {\n  type: 'text',\n  languages: ['en']\n};\n\nexport const defaultExpectedInputs: LanguageModelExpected[] = [\n  defaultExpectedText,\n  { type: 'image' }\n];\n\nexport const defaultExpectedOutputs: LanguageModelExpected[] = [\n  defaultExpectedText\n];\n\n/**\n * Defines an inference \"backend\" that uses Chrome's on-device model,\n * and encapsulates logic for detecting when on-device inference is\n * possible.\n */\nexport class ChromeAdapterImpl implements ChromeAdapter {\n  // Visible for testing\n  static SUPPORTED_MIME_TYPES = ['image/jpeg', 'image/png'];\n  // Promise for on-device model download completion\n  downloadPromise: Promise<LanguageModel | void> | null = null;\n  private oldSession: LanguageModel | undefined;\n  onDeviceParams: OnDeviceParams = {\n    createOptions: {\n      expectedInputs: defaultExpectedInputs,\n      expectedOutputs: defaultExpectedOutputs\n    }\n  };\n  constructor(\n    public languageModelProvider: LanguageModel,\n    public mode: InferenceMode,\n    onDeviceParams?: OnDeviceParams\n  ) {\n    if (onDeviceParams) {\n      this.onDeviceParams = onDeviceParams;\n      if (!this.onDeviceParams.createOptions) {\n        this.onDeviceParams.createOptions = {\n          expectedInputs: defaultExpectedInputs,\n          expectedOutputs: defaultExpectedOutputs\n        };\n      } else {\n        if (!this.onDeviceParams.createOptions.expectedInputs) {\n          this.onDeviceParams.createOptions.expectedInputs =\n            defaultExpectedInputs;\n        }\n        if (!this.onDeviceParams.createOptions.expectedOutputs) {\n          this.onDeviceParams.createOptions.expectedOutputs =\n            defaultExpectedOutputs;\n        }\n      }\n    }\n  }\n\n  /**\n   * Checks if a given request can be made on-device.\n   *\n   * Encapsulates a few concerns:\n   *   the mode\n   *   API existence\n   *   prompt formatting\n   *   model availability\n   *\n   *\n   * Pros: callers needn't be concerned with details of on-device availability.</p>\n   * Cons: this method spans a few concerns and splits request validation from usage.\n   * If instance variables weren't already part of the API, we could consider a better\n   * separation of concerns.\n   */\n  async isAvailable(request: GenerateContentRequest): Promise<boolean> {\n    if (!this.mode) {\n      logger.debug(\n        `On-device inference unavailable because mode is undefined.`\n      );\n      return false;\n    }\n    if (this.mode === InferenceMode.ONLY_IN_CLOUD) {\n      logger.debug(\n        `On-device inference unavailable because mode is \"only_in_cloud\".`\n      );\n      return false;\n    }\n\n    const availability = await this.languageModelProvider?.availability(\n      this.onDeviceParams.createOptions\n    );\n\n    if (this.mode === InferenceMode.ONLY_ON_DEVICE) {\n      // If it will never be available due to API inavailability, throw.\n      if (availability === Availability.UNAVAILABLE) {\n        throw new AIError(\n          AIErrorCode.API_NOT_ENABLED,\n          'Local LanguageModel API not available in this environment.'\n        );\n      } else if (\n        availability === Availability.DOWNLOADABLE ||\n        availability === Availability.DOWNLOADING\n      ) {\n        logger.debug(`Waiting for download of LanguageModel to complete.`);\n        try {\n          await this.downloadPromise;\n        } catch (e) {\n          throw new AIError(AIErrorCode.ERROR, (e as Error).message);\n        }\n        return true;\n      }\n      return true;\n    }\n\n    // Applies prefer_on_device logic.\n    if (availability !== Availability.AVAILABLE) {\n      logger.debug(\n        `On-device inference unavailable because availability is \"${availability}\".`\n      );\n      return false;\n    }\n    if (!ChromeAdapterImpl.isOnDeviceRequest(request)) {\n      logger.debug(\n        `On-device inference unavailable because request is incompatible.`\n      );\n      return false;\n    }\n\n    return true;\n  }\n\n  /**\n   * Generates content on device.\n   *\n   * @remarks\n   * This is comparable to {@link GenerativeModel.generateContent} for generating content in\n   * Cloud.\n   * @param request - a standard Firebase AI {@link GenerateContentRequest}\n   * @returns {@link Response}, so we can reuse common response formatting.\n   */\n  async generateContent(request: GenerateContentRequest): Promise<Response> {\n    const session = await this.createSession();\n    const contents = await Promise.all(\n      request.contents.map(ChromeAdapterImpl.toLanguageModelMessage)\n    );\n    const text = await session.prompt(\n      contents,\n      this.onDeviceParams.promptOptions\n    );\n    return ChromeAdapterImpl.toResponse(text);\n  }\n\n  /**\n   * Generates content stream on device.\n   *\n   * @remarks\n   * This is comparable to {@link GenerativeModel.generateContentStream} for generating content in\n   * Cloud.\n   * @param request - a standard Firebase AI {@link GenerateContentRequest}\n   * @returns {@link Response}, so we can reuse common response formatting.\n   */\n  async generateContentStream(\n    request: GenerateContentRequest\n  ): Promise<Response> {\n    const session = await this.createSession();\n    const contents = await Promise.all(\n      request.contents.map(ChromeAdapterImpl.toLanguageModelMessage)\n    );\n    const stream = session.promptStreaming(\n      contents,\n      this.onDeviceParams.promptOptions\n    );\n    return ChromeAdapterImpl.toStreamResponse(stream);\n  }\n\n  async countTokens(_request: CountTokensRequest): Promise<Response> {\n    throw new AIError(\n      AIErrorCode.REQUEST_ERROR,\n      'Count Tokens is not yet available for on-device model.'\n    );\n  }\n\n  /**\n   * Asserts inference for the given request can be performed by an on-device model.\n   */\n  private static isOnDeviceRequest(request: GenerateContentRequest): boolean {\n    // Returns false if the prompt is empty.\n    if (request.contents.length === 0) {\n      logger.debug('Empty prompt rejected for on-device inference.');\n      return false;\n    }\n\n    for (const content of request.contents) {\n      if (content.parts.some(part => 'functionResponse' in part)) {\n        logger.debug(\n          `Content with a function response part rejected for on-device inference.`\n        );\n        return false;\n      }\n\n      // Returns false if request contains an image with an unsupported mime type.\n      for (const part of content.parts) {\n        if (\n          part.inlineData &&\n          ChromeAdapterImpl.SUPPORTED_MIME_TYPES.indexOf(\n            part.inlineData.mimeType\n          ) === -1\n        ) {\n          logger.debug(\n            `Unsupported mime type \"${part.inlineData.mimeType}\" rejected for on-device inference.`\n          );\n          return false;\n        }\n      }\n    }\n\n    return true;\n  }\n\n  /**\n   * Encapsulates logic to get availability and download a model if one is downloadable.\n   */\n  async downloadIfAvailable(\n    onDownloadProgress?: (progressValue: number) => void\n  ): Promise<Availability | undefined> {\n    const availability = await this.languageModelProvider?.availability(\n      this.onDeviceParams.createOptions\n    );\n\n    /**\n     * Download may have been automatically started by Chrome or other\n     * code, in which case we should still call create() to get a promise\n     * for when the download completes.\n     */\n    if (\n      availability === Availability.DOWNLOADABLE ||\n      availability === Availability.DOWNLOADING\n    ) {\n      this.download(onDownloadProgress);\n    }\n\n    return availability;\n  }\n\n  /**\n   * Triggers out-of-band download of an on-device model.\n   *\n   * Chrome may automatically begin a download on startup or\n   * it may trigger a download when code calls LanguageModel.create.\n   *\n   * Since Chrome manages the download, the SDK can only avoid redundant download requests by\n   * tracking if a download has previously been requested.\n   */\n  private download(onDownloadProgress?: (progressValue: number) => void): void {\n    if (this.downloadPromise) {\n      return;\n    }\n    const options = { ...this.onDeviceParams.createOptions };\n    if (options && !options.monitor && onDownloadProgress) {\n      options.monitor = m => {\n        m.addEventListener('downloadprogress', e => {\n          onDownloadProgress(e.loaded);\n        });\n      };\n    }\n    this.downloadPromise = this.languageModelProvider\n      ?.create(options)\n      .finally(() => {\n        this.downloadPromise = null;\n      });\n  }\n\n  /**\n   * Converts Firebase AI {@link Content} object to a Chrome {@link LanguageModelMessage} object.\n   */\n  private static async toLanguageModelMessage(\n    content: Content\n  ): Promise<LanguageModelMessage> {\n    const languageModelMessageContents = await Promise.all(\n      content.parts.map(ChromeAdapterImpl.toLanguageModelMessageContent)\n    );\n    return {\n      role: ChromeAdapterImpl.toLanguageModelMessageRole(content.role),\n      content: languageModelMessageContents\n    };\n  }\n\n  /**\n   * Converts a Firebase AI Part object to a Chrome LanguageModelMessageContent object.\n   */\n  private static async toLanguageModelMessageContent(\n    part: Part\n  ): Promise<LanguageModelMessageContent> {\n    if (part.text) {\n      return {\n        type: 'text',\n        value: part.text\n      };\n    } else if (part.inlineData) {\n      const formattedImageContent = await fetch(\n        `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`\n      );\n      const imageBlob = await formattedImageContent.blob();\n      const imageBitmap = await createImageBitmap(imageBlob);\n      return {\n        type: 'image',\n        value: imageBitmap\n      };\n    }\n    throw new AIError(\n      AIErrorCode.REQUEST_ERROR,\n      `Processing of this Part type is not currently supported.`\n    );\n  }\n\n  /**\n   * Converts a Firebase AI {@link Role} string to a {@link LanguageModelMessageRole} string.\n   */\n  private static toLanguageModelMessageRole(\n    role: Role\n  ): LanguageModelMessageRole {\n    // Assumes 'function' rule has been filtered by isOnDeviceRequest\n    return role === 'model' ? 'assistant' : 'user';\n  }\n\n  /**\n   * Abstracts Chrome session creation.\n   *\n   * Chrome uses a multi-turn session for all inference. Firebase AI uses single-turn for all\n   * inference. To map the Firebase AI API to Chrome's API, the SDK creates a new session for all\n   * inference.\n   *\n   * Chrome will remove a model from memory if it's no longer in use, so this method ensures a\n   * new session is created before an old session is destroyed.\n   */\n  private async createSession(): Promise<LanguageModel> {\n    if (!this.languageModelProvider) {\n      throw new AIError(\n        AIErrorCode.UNSUPPORTED,\n        'Chrome AI requested for unsupported browser version.'\n      );\n    }\n    /**\n     * Note: `create()` will trigger a download as a side effect if\n     * a model is not downloaded or downloading, but this specific\n     * create() call should not be relied on for the download. The download\n     * should be triggered explicitly by the user in\n     * GenerativeModel.initializeDeviceModel().\n     */\n    const newSession = await this.languageModelProvider.create(\n      this.onDeviceParams.createOptions\n    );\n    if (this.oldSession) {\n      this.oldSession.destroy();\n    }\n    // Holds session reference, so model isn't unloaded from memory.\n    this.oldSession = newSession;\n    return newSession;\n  }\n\n  /**\n   * Formats string returned by Chrome as a {@link Response} returned by Firebase AI.\n   */\n  private static toResponse(text: string): Response {\n    return {\n      json: async () => ({\n        candidates: [\n          {\n            content: {\n              parts: [{ text }]\n            }\n          }\n        ]\n      })\n    } as Response;\n  }\n\n  /**\n   * Formats string stream returned by Chrome as SSE returned by Firebase AI.\n   */\n  private static toStreamResponse(stream: ReadableStream<string>): Response {\n    const encoder = new TextEncoder();\n    return {\n      body: stream.pipeThrough(\n        new TransformStream({\n          transform(chunk, controller) {\n            const json = JSON.stringify({\n              candidates: [\n                {\n                  content: {\n                    role: 'model',\n                    parts: [{ text: chunk }]\n                  }\n                }\n              ]\n            });\n            controller.enqueue(encoder.encode(`data: ${json}\\n\\n`));\n          }\n        })\n      )\n    } as Response;\n  }\n}\n\n/**\n * Creates a ChromeAdapterImpl on demand.\n */\nexport function chromeAdapterFactory(\n  mode: InferenceMode,\n  window?: Window,\n  params?: OnDeviceParams\n): ChromeAdapterImpl | undefined {\n  const globalObj = window || getGlobal();\n  const languageModel = (globalObj as Record<string, unknown>).LanguageModel as\n    LanguageModel | undefined;\n  // Do not initialize a ChromeAdapter if we are not in hybrid mode.\n  if (languageModel && mode) {\n    return new ChromeAdapterImpl(languageModel, mode, params);\n  }\n}\n","/**\n * @license\n * Copyright 2024 Google LLC\n *\n * Licensed under the Apache License, Version 2.0 (the \"License\");\n * you may not use this file except in compliance with the License.\n * You may obtain a copy of the License at\n *\n *   http://www.apache.org/licenses/LICENSE-2.0\n *\n * Unless required by applicable law or agreed to in writing, software\n * distributed under the License is distributed on an \"AS IS\" BASIS,\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n * See the License for the specific language governing permissions and\n * limitations under the License.\n */\n\nimport { FirebaseApp, _FirebaseService } from '@firebase/app';\nimport {\n  AI,\n  AIOptions,\n  ChromeAdapter,\n  InferenceMode,\n  OnDeviceParams\n} from './public-types';\nimport {\n  AppCheckInternalComponentName,\n  FirebaseAppCheckInternal\n} from '@firebase/app-check-interop-types';\nimport { Provider } from '@firebase/component';\nimport {\n  FirebaseAuthInternal,\n  FirebaseAuthInternalName\n} from '@firebase/auth-interop-types';\nimport { AgentPlatformBackend, Backend, VertexAIBackend } from './backend';\n\nexport class AIService implements AI, _FirebaseService {\n  auth: FirebaseAuthInternal | null;\n  appCheck: FirebaseAppCheckInternal | null;\n  _options?: Omit<AIOptions, 'backend'>;\n  location: string; // This is here for backwards-compatibility\n\n  constructor(\n    public app: FirebaseApp,\n    public backend: Backend,\n    authProvider?: Provider<FirebaseAuthInternalName>,\n    appCheckProvider?: Provider<AppCheckInternalComponentName>,\n    public chromeAdapterFactory?: (\n      mode: InferenceMode,\n      window?: Window,\n      params?: OnDeviceParams\n    ) => ChromeAdapter | undefined\n  ) {\n    const appCheck = appCheckProvider?.getImmediate({ optional: true });\n    const auth = authProvider?.getImmediate({ optional: true });\n    this.auth = auth || null;\n    this.appCheck = appCheck || null;\n\n    if (\n      backend instanceof VertexAIBackend ||\n      backend instanceof AgentPlatformBackend\n    ) {\n      this.location = backend.location;\n    } else {\n      this.location = '';\n    }\n  }\n\n  _delete(): Promise<void> {\n    return Promise.resolve();\n  }\n\n  set options(optionsToSet: AIOptions) {\n    this._options = optionsToSet;\n  }\n\n  get options(): AIOptions | undefined {\n    return this._options;\n  }\n}\n","/**\n * @license\n * Copyright 2025 Google LLC\n *\n * Licensed under the Apache License, Version 2.0 (the \"License\");\n * you may not use this file except in compliance with the License.\n * You may obtain a copy of the License at\n *\n *   http://www.apache.org/licenses/LICENSE-2.0\n *\n * Unless required by applicable law or agreed to in writing, software\n * distributed under the License is distributed on an \"AS IS\" BASIS,\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n * See the License for the specific language governing permissions and\n * limitations under the License.\n */\n\nimport {\n  ComponentContainer,\n  InstanceFactoryOptions\n} from '@firebase/component';\nimport { AIError } from './errors';\nimport { decodeInstanceIdentifier } from './helpers';\nimport { chromeAdapterFactory } from './methods/chrome-adapter';\nimport { AIService } from './service';\nimport { AIErrorCode } from './types';\n\nexport function factory(\n  container: ComponentContainer,\n  { instanceIdentifier }: InstanceFactoryOptions\n): AIService {\n  if (!instanceIdentifier) {\n    throw new AIError(\n      AIErrorCode.ERROR,\n      'AIService instance identifier is undefined.'\n    );\n  }\n\n  const backend = decodeInstanceIdentifier(instanceIdentifier);\n\n  // getImmediate for FirebaseApp will always succeed\n  const app = container.getProvider('app').getImmediate();\n  const auth = container.getProvider('auth-internal');\n  const appCheckProvider = container.getProvider('app-check-internal');\n\n  return new AIService(\n    app,\n    backend,\n    auth,\n    appCheckProvider,\n    chromeAdapterFactory\n  );\n}\n","/**\n * @license\n * Copyright 2025 Google LLC\n *\n * Licensed under the Apache License, Version 2.0 (the \"License\");\n * you may not use this file except in compliance with the License.\n * You may obtain a copy of the License at\n *\n *   http://www.apache.org/licenses/LICENSE-2.0\n *\n * Unless required by applicable law or agreed to in writing, software\n * distributed under the License is distributed on an \"AS IS\" BASIS,\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n * See the License for the specific language governing permissions and\n * limitations under the License.\n */\n\nimport { _isFirebaseServerApp } from '@firebase/app';\nimport { AIError } from '../errors';\nimport { AI, AIErrorCode } from '../public-types';\nimport { AIService } from '../service';\nimport { ApiSettings } from '../types/internal';\n\n/**\n * Initializes an {@link ApiSettings} object from an {@link AI} instance.\n *\n * If this is a Server App, the {@link ApiSettings} object's `getAppCheckToken()` will resolve\n * with the `FirebaseServerAppSettings.appCheckToken`, instead of requiring that an App Check\n * instance is initialized.\n */\nexport function initApiSettings(ai: AI): ApiSettings {\n  if (!ai.app?.options?.apiKey) {\n    throw new AIError(\n      AIErrorCode.NO_API_KEY,\n      `The \"apiKey\" field is empty in the local Firebase config. Firebase AI requires this field to contain a valid API key.`\n    );\n  } else if (!ai.app?.options?.projectId) {\n    throw new AIError(\n      AIErrorCode.NO_PROJECT_ID,\n      `The \"projectId\" field is empty in the local Firebase config. Firebase AI requires this field to contain a valid project ID.`\n    );\n  } else if (!ai.app?.options?.appId) {\n    throw new AIError(\n      AIErrorCode.NO_APP_ID,\n      `The \"appId\" field is empty in the local Firebase config. Firebase AI requires this field to contain a valid app ID.`\n    );\n  }\n\n  const apiSettings: ApiSettings = {\n    apiKey: ai.app.options.apiKey,\n    project: ai.app.options.projectId,\n    appId: ai.app.options.appId,\n    automaticDataCollectionEnabled: ai.app.automaticDataCollectionEnabled,\n    location: ai.location,\n    backend: ai.backend\n  };\n\n  if (_isFirebaseServerApp(ai.app) && ai.app.settings.appCheckToken) {\n    const token = ai.app.settings.appCheckToken;\n    apiSettings.getAppCheckToken = () => {\n      return Promise.resolve({ token });\n    };\n  } else if ((ai as AIService).appCheck) {\n    if (ai.options?.useLimitedUseAppCheckTokens) {\n      apiSettings.getAppCheckToken = () =>\n        (ai as AIService).appCheck!.getLimitedUseToken();\n    } else {\n      apiSettings.getAppCheckToken = () =>\n        (ai as AIService).appCheck!.getToken();\n    }\n  }\n\n  if ((ai as AIService).auth) {\n    apiSettings.getAuthToken = () => (ai as AIService).auth!.getToken();\n  }\n\n  return apiSettings;\n}\n","/**\n * @license\n * Copyright 2025 Google LLC\n *\n * Licensed under the Apache License, Version 2.0 (the \"License\");\n * you may not use this file except in compliance with the License.\n * You may obtain a copy of the License at\n *\n *   http://www.apache.org/licenses/LICENSE-2.0\n *\n * Unless required by applicable law or agreed to in writing, software\n * distributed under the License is distributed on an \"AS IS\" BASIS,\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n * See the License for the specific language governing permissions and\n * limitations under the License.\n */\n\nimport { AI, BackendType } from '../public-types';\nimport { ApiSettings } from '../types/internal';\nimport { initApiSettings } from './utils';\n\n/**\n * Base class for Firebase AI model APIs.\n *\n * Instances of this class are associated with a specific Firebase AI {@link Backend}\n * and provide methods for interacting with the configured generative model.\n *\n * @public\n */\nexport abstract class AIModel {\n  /**\n   * The fully qualified model resource name\n   * (for example, `publishers/google/models/gemini-3.6-flash`).\n   */\n  readonly model: string;\n\n  /**\n   * @internal\n   */\n  _apiSettings: ApiSettings;\n\n  /**\n   * Constructs a new instance of the {@link AIModel} class.\n   *\n   * This constructor should only be called from subclasses that provide\n   * a model API.\n   *\n   * @param ai - an {@link AI} instance.\n   * @param modelName - The name of the model being used. It can be in one of the following formats:\n   * - `my-model` (short name, will resolve to `publishers/google/models/my-model`)\n   * - `models/my-model` (will resolve to `publishers/google/models/my-model`)\n   * - `publishers/my-publisher/models/my-model` (fully qualified model name)\n   *\n   * @throws If the `apiKey` or `projectId` fields are missing in your\n   * Firebase config.\n   *\n   * @internal\n   */\n  protected constructor(ai: AI, modelName: string) {\n    this._apiSettings = initApiSettings(ai);\n    this.model = AIModel.normalizeModelName(\n      modelName,\n      this._apiSettings.backend.backendType\n    );\n  }\n\n  /**\n   * Normalizes the given model name to a fully qualified model resource name.\n   *\n   * @param modelName - The model name to normalize.\n   * @returns The fully qualified model resource name.\n   *\n   * @internal\n   */\n  static normalizeModelName(\n    modelName: string,\n    backendType: BackendType\n  ): string {\n    if (backendType === BackendType.GOOGLE_AI) {\n      return AIModel.normalizeGoogleAIModelName(modelName);\n    } else {\n      return AIModel.normalizeVertexAIModelName(modelName);\n    }\n  }\n\n  /**\n   * @internal\n   */\n  private static normalizeGoogleAIModelName(modelName: string): string {\n    return `models/${modelName}`;\n  }\n\n  /**\n   * @internal\n   */\n  private static normalizeVertexAIModelName(modelName: string): string {\n    let model: string;\n    if (modelName.includes('/')) {\n      if (modelName.startsWith('models/')) {\n        // Add 'publishers/google' if the user is only passing in 'models/model-name'.\n        model = `publishers/google/${modelName}`;\n      } else {\n        // Any other custom format (e.g. tuned models) must be passed in correctly.\n        model = modelName;\n      }\n    } else {\n      // If path is not included, assume it's a non-tuned model.\n      model = `publishers/google/models/${modelName}`;\n    }\n\n    return model;\n  }\n}\n","/**\n * @license\n * Copyright 2025 Google LLC\n *\n * Licensed under the Apache License, Version 2.0 (the \"License\");\n * you may not use this file except in compliance with the License.\n * You may obtain a copy of the License at\n *\n *   http://www.apache.org/licenses/LICENSE-2.0\n *\n * Unless required by applicable law or agreed to in writing, software\n * distributed under the License is distributed on an \"AS IS\" BASIS,\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n * See the License for the specific language governing permissions and\n * limitations under the License.\n */\n\nimport { SingleRequestOptions, AIErrorCode, ErrorDetails } from '../types';\nimport { AIError } from '../errors';\nimport { ApiSettings } from '../types/internal';\nimport {\n  DEFAULT_DOMAIN,\n  DEFAULT_FETCH_TIMEOUT_MS,\n  HYBRID_TAG,\n  LANGUAGE_TAG,\n  PACKAGE_VERSION\n} from '../constants';\nimport { logger } from '../logger';\nimport { BackendType, InferenceMode } from '../public-types';\n\nexport const TIMEOUT_EXPIRED_MESSAGE = 'Timeout has expired.';\nexport const ABORT_ERROR_NAME = 'AbortError';\n\nexport const enum Task {\n  GENERATE_CONTENT = 'generateContent',\n  STREAM_GENERATE_CONTENT = 'streamGenerateContent',\n  COUNT_TOKENS = 'countTokens'\n}\n\nexport const enum ServerPromptTemplateTask {\n  TEMPLATE_GENERATE_CONTENT = 'templateGenerateContent',\n  TEMPLATE_STREAM_GENERATE_CONTENT = 'templateStreamGenerateContent'\n}\n\ninterface BaseRequestURLParams {\n  apiSettings: ApiSettings;\n  stream: boolean;\n  singleRequestOptions?: SingleRequestOptions;\n}\n\n/**\n * Parameters used to construct the URL of a request to use a model.\n */\ninterface ModelRequestURLParams extends BaseRequestURLParams {\n  task: Task;\n  model: string;\n  templateId?: never;\n}\n\n/**\n * Parameters used to construct the URL of a request to use server side prompt templates.\n */\ninterface TemplateRequestURLParams extends BaseRequestURLParams {\n  task: ServerPromptTemplateTask;\n  templateId: string;\n  model?: never;\n}\n\nexport class RequestURL {\n  constructor(\n    public readonly params: ModelRequestURLParams | TemplateRequestURLParams\n  ) {}\n\n  toString(): string {\n    const url = new URL(this.baseUrl); // Throws if the URL is invalid\n    url.pathname = this.pathname;\n    url.search = this.queryParams.toString();\n    return url.toString();\n  }\n\n  private get pathname(): string {\n    // We need to construct a different URL if the request is for server side prompt templates,\n    // since the URL patterns are different. Server side prompt templates expect a templateId\n    // instead of a model name.\n    if (this.params.templateId) {\n      return `${this.params.apiSettings.backend._getTemplatePath(\n        this.params.apiSettings.project,\n        this.params.templateId\n      )}:${this.params.task}`;\n    } else {\n      return `${this.params.apiSettings.backend._getModelPath(\n        this.params.apiSettings.project,\n        (this.params as ModelRequestURLParams).model\n      )}:${this.params.task}`;\n    }\n  }\n\n  private get baseUrl(): string {\n    return (\n      this.params.singleRequestOptions?.baseUrl ?? `https://${DEFAULT_DOMAIN}`\n    );\n  }\n\n  private get queryParams(): URLSearchParams {\n    const params = new URLSearchParams();\n    if (this.params.stream) {\n      params.set('alt', 'sse');\n    }\n\n    return params;\n  }\n}\n\nexport class WebSocketUrl {\n  constructor(public apiSettings: ApiSettings) {}\n  toString(): string {\n    const url = new URL(`wss://${DEFAULT_DOMAIN}`);\n    url.pathname = this.pathname;\n\n    const queryParams = new URLSearchParams();\n    queryParams.set('key', this.apiSettings.apiKey);\n    url.search = queryParams.toString();\n\n    return url.toString();\n  }\n\n  private get pathname(): string {\n    if (this.apiSettings.backend.backendType === BackendType.GOOGLE_AI) {\n      return 'ws/google.firebase.vertexai.v1beta.GenerativeService/BidiGenerateContent';\n    } else {\n      return `ws/google.firebase.vertexai.v1beta.LlmBidiService/BidiGenerateContent/locations/${this.apiSettings.location}`;\n    }\n  }\n}\n\n/**\n * Log language and \"fire/version\" to x-goog-api-client\n */\nfunction getClientHeaders(url: RequestURL): string {\n  const loggingTags = [];\n  loggingTags.push(`${LANGUAGE_TAG}/${PACKAGE_VERSION}`);\n  loggingTags.push(`fire/${PACKAGE_VERSION}`);\n  /**\n   * No call would be made if ONLY_ON_DEVICE.\n   * ONLY_IN_CLOUD does not indicate an intention to use hybrid.\n   */\n  if (\n    url.params.apiSettings.inferenceMode === InferenceMode.PREFER_ON_DEVICE ||\n    url.params.apiSettings.inferenceMode === InferenceMode.PREFER_IN_CLOUD\n  ) {\n    // No version\n    loggingTags.push(HYBRID_TAG);\n  }\n  return loggingTags.join(' ');\n}\n\nexport async function getHeaders(url: RequestURL): Promise<Headers> {\n  const headers = new Headers();\n  headers.append('Content-Type', 'application/json');\n  headers.append('x-goog-api-client', getClientHeaders(url));\n  headers.append('x-goog-api-key', url.params.apiSettings.apiKey);\n  if (url.params.apiSettings.automaticDataCollectionEnabled) {\n    headers.append('X-Firebase-Appid', url.params.apiSettings.appId);\n  }\n  if (url.params.apiSettings.getAppCheckToken) {\n    const appCheckToken = await url.params.apiSettings.getAppCheckToken();\n    if (appCheckToken) {\n      headers.append('X-Firebase-AppCheck', appCheckToken.token);\n      if (appCheckToken.error) {\n        logger.warn(\n          `Unable to obtain a valid App Check token: ${appCheckToken.error.message}`\n        );\n      }\n    }\n  }\n\n  if (url.params.apiSettings.getAuthToken) {\n    const authToken = await url.params.apiSettings.getAuthToken();\n    if (authToken) {\n      headers.append('Authorization', `Firebase ${authToken.accessToken}`);\n    }\n  }\n\n  return headers;\n}\n\nexport async function makeRequest(\n  requestUrlParams: TemplateRequestURLParams | ModelRequestURLParams,\n  body: string\n): Promise<Response> {\n  const url = new RequestURL(requestUrlParams);\n  let response;\n\n  const externalSignal = requestUrlParams.singleRequestOptions?.signal;\n  const timeoutMillis =\n    requestUrlParams.singleRequestOptions?.timeout != null &&\n    requestUrlParams.singleRequestOptions.timeout >= 0\n      ? requestUrlParams.singleRequestOptions.timeout\n      : DEFAULT_FETCH_TIMEOUT_MS;\n\n  const internalAbortController = new AbortController();\n  const fetchTimeoutId = setTimeout(() => {\n    internalAbortController.abort(\n      new DOMException(TIMEOUT_EXPIRED_MESSAGE, ABORT_ERROR_NAME)\n    );\n    logger.debug(\n      `Aborting request to ${url} due to timeout (${timeoutMillis}ms)`\n    );\n  }, timeoutMillis);\n\n  // Used to abort the fetch if either the user-defined `externalSignal` is aborted, or if the\n  // internal signal (triggered by timeouts) is aborted.\n  const combinedSignal = AbortSignal.any(\n    externalSignal\n      ? [externalSignal, internalAbortController.signal]\n      : [internalAbortController.signal]\n  );\n\n  if (externalSignal && externalSignal.aborted) {\n    clearTimeout(fetchTimeoutId);\n    throw new DOMException(\n      externalSignal.reason ?? 'Aborted externally before fetch',\n      ABORT_ERROR_NAME\n    );\n  }\n\n  try {\n    const fetchOptions: RequestInit = {\n      method: 'POST',\n      headers: await getHeaders(url),\n      signal: combinedSignal,\n      body\n    };\n\n    response = await fetch(url.toString(), fetchOptions);\n    if (!response.ok) {\n      let message = '';\n      let errorDetails;\n      try {\n        const json = await response.json();\n        message = json.error.message;\n        if (json.error.details) {\n          message += ` ${JSON.stringify(json.error.details)}`;\n          errorDetails = json.error.details;\n        }\n      } catch (e) {\n        // ignored\n      }\n      if (\n        response.status === 403 &&\n        errorDetails &&\n        errorDetails.some(\n          (detail: ErrorDetails) => detail.reason === 'SERVICE_DISABLED'\n        ) &&\n        errorDetails.some((detail: ErrorDetails) =>\n          (\n            detail.links as Array<Record<string, string>>\n          )?.[0]?.description.includes(\n            'Google developers console API activation'\n          )\n        )\n      ) {\n        throw new AIError(\n          AIErrorCode.API_NOT_ENABLED,\n          `The Firebase AI SDK requires the Firebase AI ` +\n            `API ('firebasevertexai.googleapis.com') to be enabled in your ` +\n            `Firebase project. Enable this API by visiting the Firebase Console ` +\n            `at https://console.firebase.google.com/project/${url.params.apiSettings.project}/ailogic/ ` +\n            `and clicking \"Get started\". If you enabled this API recently, ` +\n            `wait a few minutes for the action to propagate to our systems and ` +\n            `then retry.`,\n          {\n            status: response.status,\n            statusText: response.statusText,\n            errorDetails\n          }\n        );\n      }\n      throw new AIError(\n        AIErrorCode.FETCH_ERROR,\n        `Error fetching from ${url}: [${response.status} ${response.statusText}] ${message}`,\n        {\n          status: response.status,\n          statusText: response.statusText,\n          errorDetails\n        }\n      );\n    }\n  } catch (e) {\n    let err = e as Error;\n    if (\n      (e as AIError).code !== AIErrorCode.FETCH_ERROR &&\n      (e as AIError).code !== AIErrorCode.API_NOT_ENABLED &&\n      e instanceof Error &&\n      (e as DOMException).name !== ABORT_ERROR_NAME\n    ) {\n      err = new AIError(\n        AIErrorCode.ERROR,\n        `Error fetching from ${url.toString()}: ${e.message}`\n      );\n      err.stack = e.stack;\n    }\n\n    throw err;\n  } finally {\n    // When doing streaming requests, this will clear the timeout once the stream begins.\n    // If a timeout it 3000ms, and the stream starts after 300ms and ends after 5000ms, the\n    // timeout will be cleared after 300ms, so it won't abort the request.\n    clearTimeout(fetchTimeoutId);\n  }\n  return response;\n}\n","/**\n * @license\n * Copyright 2024 Google LLC\n *\n * Licensed under the Apache License, Version 2.0 (the \"License\");\n * you may not use this file except in compliance with the License.\n * You may obtain a copy of the License at\n *\n *   http://www.apache.org/licenses/LICENSE-2.0\n *\n * Unless required by applicable law or agreed to in writing, software\n * distributed under the License is distributed on an \"AS IS\" BASIS,\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n * See the License for the specific language governing permissions and\n * limitations under the License.\n */\n\nimport {\n  EnhancedGenerateContentResponse,\n  FinishReason,\n  FunctionCall,\n  GenerateContentCandidate,\n  GenerateContentResponse,\n  AIErrorCode,\n  InlineDataPart,\n  Part,\n  InferenceSource\n} from '../types';\nimport { AIError } from '../errors';\nimport { logger } from '../logger';\n\n/**\n * Check that at least one candidate exists and does not have a bad\n * finish reason. Warns if multiple candidates exist.\n */\nfunction hasValidCandidates(response: GenerateContentResponse): boolean {\n  if (response.candidates && response.candidates.length > 0) {\n    if (response.candidates.length > 1) {\n      logger.warn(\n        `This response had ${response.candidates.length} ` +\n          `candidates. Returning text from the first candidate only. ` +\n          `Access response.candidates directly to use the other candidates.`\n      );\n    }\n    if (hadBadFinishReason(response.candidates[0])) {\n      throw new AIError(\n        AIErrorCode.RESPONSE_ERROR,\n        `Response error: ${formatBlockErrorMessage(\n          response\n        )}. Response body stored in error.response`,\n        {\n          response\n        }\n      );\n    }\n    return true;\n  } else {\n    return false;\n  }\n}\n\n/**\n * Creates an EnhancedGenerateContentResponse object that has helper functions and\n * other modifications that improve usability.\n */\nexport function createEnhancedContentResponse(\n  response: GenerateContentResponse,\n  inferenceSource: InferenceSource = InferenceSource.IN_CLOUD\n): EnhancedGenerateContentResponse {\n  /**\n   * The AgentPlatform backend omits default values.\n   * This causes the `index` property to be omitted from the first candidate in the\n   * response, since it has index 0, and 0 is a default value.\n   * See: https://github.com/firebase/firebase-js-sdk/issues/8566\n   */\n  if (response.candidates && !response.candidates[0].hasOwnProperty('index')) {\n    response.candidates[0].index = 0;\n  }\n\n  const responseWithHelpers = addHelpers(response);\n  responseWithHelpers.inferenceSource = inferenceSource;\n  return responseWithHelpers;\n}\n\n/**\n * Adds convenience helper methods to a response object, including stream\n * chunks (as long as each chunk is a complete GenerateContentResponse JSON).\n */\nexport function addHelpers(\n  response: GenerateContentResponse\n): EnhancedGenerateContentResponse {\n  (response as EnhancedGenerateContentResponse).text = () => {\n    if (hasValidCandidates(response)) {\n      return getText(response, part => !part.thought);\n    } else if (response.promptFeedback) {\n      throw new AIError(\n        AIErrorCode.RESPONSE_ERROR,\n        `Text not available. ${formatBlockErrorMessage(response)}`,\n        {\n          response\n        }\n      );\n    }\n    return '';\n  };\n  (response as EnhancedGenerateContentResponse).thoughtSummary = () => {\n    if (hasValidCandidates(response)) {\n      const result = getText(response, part => !!part.thought);\n      return result === '' ? undefined : result;\n    } else if (response.promptFeedback) {\n      throw new AIError(\n        AIErrorCode.RESPONSE_ERROR,\n        `Thought summary not available. ${formatBlockErrorMessage(response)}`,\n        {\n          response\n        }\n      );\n    }\n    return undefined;\n  };\n  (response as EnhancedGenerateContentResponse).inlineDataParts = ():\n    InlineDataPart[] | undefined => {\n    if (hasValidCandidates(response)) {\n      return getInlineDataParts(response);\n    } else if (response.promptFeedback) {\n      throw new AIError(\n        AIErrorCode.RESPONSE_ERROR,\n        `Data not available. ${formatBlockErrorMessage(response)}`,\n        {\n          response\n        }\n      );\n    }\n    return undefined;\n  };\n  (response as EnhancedGenerateContentResponse).functionCalls = () => {\n    if (hasValidCandidates(response)) {\n      return getFunctionCalls(response);\n    } else if (response.promptFeedback) {\n      throw new AIError(\n        AIErrorCode.RESPONSE_ERROR,\n        `Function call not available. ${formatBlockErrorMessage(response)}`,\n        {\n          response\n        }\n      );\n    }\n    return undefined;\n  };\n  return response as EnhancedGenerateContentResponse;\n}\n\n/**\n * Returns all text from the first candidate's parts, filtering by whether\n * `partFilter()` returns true.\n *\n * @param response - The `GenerateContentResponse` from which to extract text.\n * @param partFilter - Only return `Part`s for which this returns true\n */\nexport function getText(\n  response: GenerateContentResponse,\n  partFilter: (part: Part) => boolean\n): string {\n  const textStrings = [];\n  if (response.candidates?.[0].content?.parts) {\n    for (const part of response.candidates?.[0].content?.parts) {\n      if (part.text && partFilter(part)) {\n        textStrings.push(part.text);\n      }\n    }\n  }\n  if (textStrings.length > 0) {\n    return textStrings.join('');\n  } else {\n    return '';\n  }\n}\n\n/**\n * Returns every {@link FunctionCall} associated with first candidate.\n */\nexport function getFunctionCalls(\n  response?: GenerateContentResponse\n): FunctionCall[] | undefined {\n  if (!response) {\n    return undefined;\n  }\n  const functionCalls: FunctionCall[] = [];\n  if (response.candidates?.[0].content?.parts) {\n    for (const part of response.candidates?.[0].content?.parts) {\n      if (part.functionCall) {\n        functionCalls.push(part.functionCall);\n      }\n    }\n  }\n  if (functionCalls.length > 0) {\n    return functionCalls;\n  } else {\n    return undefined;\n  }\n}\n\n/**\n * Returns every {@link InlineDataPart} in the first candidate if present.\n *\n * @internal\n */\nexport function getInlineDataParts(\n  response: GenerateContentResponse\n): InlineDataPart[] | undefined {\n  const data: InlineDataPart[] = [];\n\n  if (response.candidates?.[0].content?.parts) {\n    for (const part of response.candidates?.[0].content?.parts) {\n      if (part.inlineData) {\n        data.push(part);\n      }\n    }\n  }\n\n  if (data.length > 0) {\n    return data;\n  } else {\n    return undefined;\n  }\n}\n\nconst badFinishReasons = [\n  FinishReason.RECITATION,\n  FinishReason.SAFETY,\n  FinishReason.BLOCKLIST,\n  FinishReason.PROHIBITED_CONTENT,\n  FinishReason.SPII,\n  FinishReason.MALFORMED_FUNCTION_CALL,\n  FinishReason.IMAGE_SAFETY,\n  FinishReason.IMAGE_PROHIBITED_CONTENT,\n  FinishReason.IMAGE_OTHER,\n  FinishReason.NO_IMAGE,\n  FinishReason.IMAGE_RECITATION,\n  FinishReason.LANGUAGE,\n  FinishReason.UNEXPECTED_TOOL_CALL,\n  FinishReason.TOO_MANY_TOOL_CALLS,\n  FinishReason.MISSING_THOUGHT_SIGNATURE,\n  FinishReason.MALFORMED_RESPONSE\n];\n\nfunction hadBadFinishReason(candidate: GenerateContentCandidate): boolean {\n  return (\n    !!candidate.finishReason &&\n    badFinishReasons.some(reason => reason === candidate.finishReason)\n  );\n}\n\nexport function formatBlockErrorMessage(\n  response: GenerateContentResponse\n): string {\n  let message = '';\n  if (\n    (!response.candidates || response.candidates.length === 0) &&\n    response.promptFeedback\n  ) {\n    message += 'Response was blocked';\n    if (response.promptFeedback?.blockReason) {\n      message += ` due to ${response.promptFeedback.blockReason}`;\n    }\n    if (response.promptFeedback?.blockReasonMessage) {\n      message += `: ${response.promptFeedback.blockReasonMessage}`;\n    }\n  } else if (response.candidates?.[0]) {\n    const firstCandidate = response.candidates[0];\n    if (hadBadFinishReason(firstCandidate)) {\n      message += `Candidate was blocked due to ${firstCandidate.finishReason}`;\n      if (firstCandidate.finishMessage) {\n        message += `: ${firstCandidate.finishMessage}`;\n      }\n    }\n  }\n  return message;\n}\n","/**\n * @license\n * Copyright 2025 Google LLC\n *\n * Licensed under the Apache License, Version 2.0 (the \"License\");\n * you may not use this file except in compliance with the License.\n * You may obtain a copy of the License at\n *\n *   http://www.apache.org/licenses/LICENSE-2.0\n *\n * Unless required by applicable law or agreed to in writing, software\n * distributed under the License is distributed on an \"AS IS\" BASIS,\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n * See the License for the specific language governing permissions and\n * limitations under the License.\n */\n\nimport { AIError } from './errors';\nimport { logger } from './logger';\nimport {\n  CitationMetadata,\n  CountTokensRequest,\n  GenerateContentCandidate,\n  GenerateContentRequest,\n  GenerateContentResponse,\n  HarmSeverity,\n  InlineDataPart,\n  PromptFeedback,\n  SafetyRating,\n  AIErrorCode\n} from './types';\nimport {\n  GoogleAIGenerateContentResponse,\n  GoogleAIGenerateContentCandidate,\n  GoogleAICountTokensRequest\n} from './types/googleai';\n\n/**\n * This SDK supports both the Agent Platform Gemini API and the Gemini Developer API (using Google AI).\n * The public API prioritizes the format used by the Agent Platform Gemini API.\n * We avoid having two sets of types by translating requests and responses between the two API formats.\n * This translation allows developers to switch between the Agent Platform Gemini API and the Gemini Developer API\n * with minimal code changes.\n *\n * In here are functions that map requests and responses between the two API formats.\n * Requests in the AgentPlatform format are mapped to the Google AI format before being sent.\n * Responses from the Google AI backend are mapped back to the AgentPlatform format before being returned to the user.\n */\n\n/**\n * Maps a AgentPlatform {@link GenerateContentRequest} to a format that can be sent to Google AI.\n *\n * @param generateContentRequest The {@link GenerateContentRequest} to map.\n * @returns A {@link GenerateContentResponse} that conforms to the Google AI format.\n *\n * @throws If the request contains properties that are unsupported by Google AI.\n *\n * @internal\n */\nexport function mapGenerateContentRequest(\n  generateContentRequest: GenerateContentRequest\n): GenerateContentRequest {\n  generateContentRequest.safetySettings?.forEach(safetySetting => {\n    if (safetySetting.method) {\n      throw new AIError(\n        AIErrorCode.UNSUPPORTED,\n        'SafetySetting.method is not supported in the the Gemini Developer API. Please remove this property.'\n      );\n    }\n  });\n\n  if (generateContentRequest.generationConfig?.topK) {\n    const roundedTopK = Math.round(\n      generateContentRequest.generationConfig.topK\n    );\n\n    if (roundedTopK !== generateContentRequest.generationConfig.topK) {\n      logger.warn(\n        'topK in GenerationConfig has been rounded to the nearest integer to match the format for requests to the Gemini Developer API.'\n      );\n      generateContentRequest.generationConfig.topK = roundedTopK;\n    }\n  }\n\n  return generateContentRequest;\n}\n\n/**\n * Maps a {@link GenerateContentResponse} from Google AI to the format of the\n * {@link GenerateContentResponse} that we get from AgentPlatform that is exposed in the public API.\n *\n * @param googleAIResponse The {@link GenerateContentResponse} from Google AI.\n * @returns A {@link GenerateContentResponse} that conforms to the public API's format.\n *\n * @internal\n */\nexport function mapGenerateContentResponse(\n  googleAIResponse: GoogleAIGenerateContentResponse\n): GenerateContentResponse {\n  const generateContentResponse = {\n    candidates: googleAIResponse.candidates\n      ? mapGenerateContentCandidates(googleAIResponse.candidates)\n      : undefined,\n    prompt: googleAIResponse.promptFeedback\n      ? mapPromptFeedback(googleAIResponse.promptFeedback)\n      : undefined,\n    usageMetadata: googleAIResponse.usageMetadata\n  };\n\n  return generateContentResponse;\n}\n\n/**\n * Maps a AgentPlatform {@link CountTokensRequest} to a format that can be sent to Google AI.\n *\n * @param countTokensRequest The {@link CountTokensRequest} to map.\n * @param model The model to count tokens with.\n * @returns A {@link CountTokensRequest} that conforms to the Google AI format.\n *\n * @internal\n */\nexport function mapCountTokensRequest(\n  countTokensRequest: CountTokensRequest,\n  model: string\n): GoogleAICountTokensRequest {\n  const mappedCountTokensRequest: GoogleAICountTokensRequest = {\n    generateContentRequest: {\n      model,\n      ...countTokensRequest\n    }\n  };\n\n  return mappedCountTokensRequest;\n}\n\n/**\n * Maps a Google AI {@link GoogleAIGenerateContentCandidate} to a format that conforms\n * to the AgentPlatform API format.\n *\n * @param candidates The {@link GoogleAIGenerateContentCandidate} to map.\n * @returns A {@link GenerateContentCandidate} that conforms to the AgentPlatform format.\n *\n * @throws If any {@link Part} in the candidates has a `videoMetadata` property.\n *\n * @internal\n */\nexport function mapGenerateContentCandidates(\n  candidates: GoogleAIGenerateContentCandidate[]\n): GenerateContentCandidate[] {\n  const mappedCandidates: GenerateContentCandidate[] = [];\n  let mappedSafetyRatings: SafetyRating[];\n  if (mappedCandidates) {\n    candidates.forEach(candidate => {\n      // Map citationSources to citations.\n      let citationMetadata: CitationMetadata | undefined;\n      if (candidate.citationMetadata) {\n        citationMetadata = {\n          citations: candidate.citationMetadata.citationSources\n        };\n      }\n\n      // Assign missing candidate SafetyRatings properties to their defaults if undefined.\n      if (candidate.safetyRatings) {\n        mappedSafetyRatings = candidate.safetyRatings.map(safetyRating => {\n          return {\n            ...safetyRating,\n            severity:\n              safetyRating.severity ?? HarmSeverity.HARM_SEVERITY_UNSUPPORTED,\n            probabilityScore: safetyRating.probabilityScore ?? 0,\n            severityScore: safetyRating.severityScore ?? 0\n          };\n        });\n      }\n\n      // videoMetadata is not supported.\n      // Throw early since developers may send a long video as input and only expect to pay\n      // for inference on a small portion of the video.\n      if (\n        candidate.content?.parts?.some(\n          part => (part as InlineDataPart)?.videoMetadata\n        )\n      ) {\n        throw new AIError(\n          AIErrorCode.UNSUPPORTED,\n          'Part.videoMetadata is not supported in the Gemini Developer API. Please remove this property.'\n        );\n      }\n\n      const mappedCandidate = {\n        index: candidate.index,\n        content: candidate.content,\n        finishReason: candidate.finishReason,\n        finishMessage: candidate.finishMessage,\n        safetyRatings: mappedSafetyRatings,\n        citationMetadata,\n        groundingMetadata: candidate.groundingMetadata,\n        urlContextMetadata: candidate.urlContextMetadata\n      };\n      mappedCandidates.push(mappedCandidate);\n    });\n  }\n\n  return mappedCandidates;\n}\n\nexport function mapPromptFeedback(\n  promptFeedback: PromptFeedback\n): PromptFeedback {\n  // Assign missing SafetyRating properties to their defaults if undefined.\n  const mappedSafetyRatings: SafetyRating[] = [];\n  promptFeedback.safetyRatings.forEach(safetyRating => {\n    mappedSafetyRatings.push({\n      category: safetyRating.category,\n      probability: safetyRating.probability,\n      severity: safetyRating.severity ?? HarmSeverity.HARM_SEVERITY_UNSUPPORTED,\n      probabilityScore: safetyRating.probabilityScore ?? 0,\n      severityScore: safetyRating.severityScore ?? 0,\n      blocked: safetyRating.blocked\n    });\n  });\n\n  const mappedPromptFeedback: PromptFeedback = {\n    blockReason: promptFeedback.blockReason,\n    safetyRatings: mappedSafetyRatings,\n    blockReasonMessage: promptFeedback.blockReasonMessage\n  };\n  return mappedPromptFeedback;\n}\n","/**\n * @license\n * Copyright 2024 Google LLC\n *\n * Licensed under the Apache License, Version 2.0 (the \"License\");\n * you may not use this file except in compliance with the License.\n * You may obtain a copy of the License at\n *\n *   http://www.apache.org/licenses/LICENSE-2.0\n *\n * Unless required by applicable law or agreed to in writing, software\n * distributed under the License is distributed on an \"AS IS\" BASIS,\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n * See the License for the specific language governing permissions and\n * limitations under the License.\n */\n\nimport {\n  EnhancedGenerateContentResponse,\n  GenerateContentCandidate,\n  GenerateContentResponse,\n  GenerateContentStreamResult,\n  Part,\n  AIErrorCode\n} from '../types';\nimport { AIError } from '../errors';\nimport { createEnhancedContentResponse } from './response-helpers';\nimport * as GoogleAIMapper from '../googleai-mappers';\nimport { GoogleAIGenerateContentResponse } from '../types/googleai';\nimport { ApiSettings } from '../types/internal';\nimport {\n  BackendType,\n  InferenceSource,\n  URLContextMetadata\n} from '../public-types';\n\nconst responseLineRE = /^data\\: (.*)(?:\\n\\n|\\r\\r|\\r\\n\\r\\n)/;\n\n/**\n * Process a response.body stream from the backend and return an\n * iterator that provides one complete GenerateContentResponse at a time\n * and a promise that resolves with a single aggregated\n * GenerateContentResponse.\n *\n * @param response - Response from a fetch call\n */\nexport async function processStream(\n  response: Response,\n  apiSettings: ApiSettings,\n  inferenceSource?: InferenceSource\n): Promise<\n  GenerateContentStreamResult & { firstValue?: GenerateContentResponse }\n> {\n  const inputStream = response.body!.pipeThrough(\n    new TextDecoderStream('utf8', { fatal: true })\n  );\n\n  const responseStream =\n    getResponseStream<GenerateContentResponse>(inputStream);\n\n  // We split the stream so the user can iterate over partial results (stream1)\n  // while we aggregate the full result for history/final response (stream2).\n  const [stream1, stream2] = responseStream.tee();\n  const { response: internalResponse, firstValue } =\n    await processStreamInternal(stream2, apiSettings, inferenceSource);\n  return {\n    stream: generateResponseSequence(stream1, apiSettings, inferenceSource),\n    response: internalResponse,\n    firstValue\n  };\n}\n\n/**\n * Consumes streams teed from the input stream for internal needs.\n * The streams need to be teed because each stream can only be consumed\n * by one reader.\n *\n * \"streamForPeek\"\n * This tee is used to peek at the first value for relevant information\n * that we need to evaluate before returning the stream handle to the\n * client. For example, we need to check if the response is a function\n * call that may need to be handled by automatic function calling before\n * returning a response to the client.\n *\n * \"streamForAggregation\"\n * We iterate through this tee independently from the user and aggregate\n * it into a single response when the stream is complete. We need this\n * aggregate object to add to chat history when using ChatSession. It's\n * also provided to the user if they want it.\n */\nasync function processStreamInternal(\n  stream: ReadableStream<GenerateContentResponse>,\n  apiSettings: ApiSettings,\n  inferenceSource?: InferenceSource\n): Promise<{\n  firstValue?: GenerateContentResponse;\n  response: Promise<EnhancedGenerateContentResponse>;\n}> {\n  const [streamForPeek, streamForAggregation] = stream.tee();\n  const reader = streamForPeek.getReader();\n  const { value } = await reader.read();\n  return {\n    firstValue: value,\n    response: getResponsePromise(\n      streamForAggregation,\n      apiSettings,\n      inferenceSource\n    )\n  };\n}\n\nasync function getResponsePromise(\n  stream: ReadableStream<GenerateContentResponse>,\n  apiSettings: ApiSettings,\n  inferenceSource?: InferenceSource\n): Promise<EnhancedGenerateContentResponse> {\n  const allResponses: GenerateContentResponse[] = [];\n  const reader = stream.getReader();\n  while (true) {\n    const { done, value } = await reader.read();\n    if (done) {\n      let generateContentResponse = aggregateResponses(allResponses);\n      if (apiSettings.backend.backendType === BackendType.GOOGLE_AI) {\n        generateContentResponse = GoogleAIMapper.mapGenerateContentResponse(\n          generateContentResponse as GoogleAIGenerateContentResponse\n        );\n      }\n      return createEnhancedContentResponse(\n        generateContentResponse,\n        inferenceSource\n      );\n    }\n    allResponses.push(value);\n  }\n}\n\nasync function* generateResponseSequence(\n  stream: ReadableStream<GenerateContentResponse>,\n  apiSettings: ApiSettings,\n  inferenceSource?: InferenceSource\n): AsyncGenerator<EnhancedGenerateContentResponse> {\n  const reader = stream.getReader();\n  while (true) {\n    const { value, done } = await reader.read();\n    if (done) {\n      break;\n    }\n\n    let enhancedResponse: EnhancedGenerateContentResponse;\n    if (apiSettings.backend.backendType === BackendType.GOOGLE_AI) {\n      enhancedResponse = createEnhancedContentResponse(\n        GoogleAIMapper.mapGenerateContentResponse(\n          value as GoogleAIGenerateContentResponse\n        ),\n        inferenceSource\n      );\n    } else {\n      enhancedResponse = createEnhancedContentResponse(value, inferenceSource);\n    }\n\n    const firstCandidate = enhancedResponse.candidates?.[0];\n    if (\n      !firstCandidate?.content?.parts &&\n      !firstCandidate?.finishReason &&\n      !firstCandidate?.citationMetadata &&\n      !firstCandidate?.urlContextMetadata\n    ) {\n      continue;\n    }\n\n    yield enhancedResponse;\n  }\n}\n\n/**\n * Reads a raw string stream, buffers incomplete chunks, and yields parsed JSON objects.\n */\nexport function getResponseStream<T>(\n  inputStream: ReadableStream<string>\n): ReadableStream<T> {\n  const reader = inputStream.getReader();\n  const stream = new ReadableStream<T>({\n    start(controller) {\n      let currentText = '';\n      return pump();\n      function pump(): Promise<(() => Promise<void>) | undefined> {\n        return reader.read().then(({ value, done }) => {\n          if (done) {\n            if (currentText.trim()) {\n              controller.error(\n                new AIError(AIErrorCode.PARSE_FAILED, 'Failed to parse stream')\n              );\n              return;\n            }\n            controller.close();\n            return;\n          }\n\n          currentText += value;\n          // SSE events may span chunk boundaries, so we buffer until we match\n          // the full \"data: {json}\\n\\n\" pattern.\n          let match = currentText.match(responseLineRE);\n          let parsedResponse: T;\n          while (match) {\n            try {\n              parsedResponse = JSON.parse(match[1]);\n            } catch (e) {\n              controller.error(\n                new AIError(\n                  AIErrorCode.PARSE_FAILED,\n                  `Error parsing JSON response: \"${match[1]}`\n                )\n              );\n              return;\n            }\n            controller.enqueue(parsedResponse);\n            currentText = currentText.substring(match[0].length);\n            match = currentText.match(responseLineRE);\n          }\n          return pump();\n        });\n      }\n    }\n  });\n  return stream;\n}\n\n/**\n * Aggregates an array of `GenerateContentResponse`s into a single\n * GenerateContentResponse.\n */\nexport function aggregateResponses(\n  responses: GenerateContentResponse[]\n): GenerateContentResponse {\n  const lastResponse = responses[responses.length - 1];\n  const aggregatedResponse: GenerateContentResponse = {\n    promptFeedback: lastResponse?.promptFeedback\n  };\n  for (const response of responses) {\n    if (response.candidates) {\n      for (const candidate of response.candidates) {\n        // Use 0 if index is undefined (protobuf default value omission).\n        const i = candidate.index || 0;\n        if (!aggregatedResponse.candidates) {\n          aggregatedResponse.candidates = [];\n        }\n        if (!aggregatedResponse.candidates[i]) {\n          aggregatedResponse.candidates[i] = {\n            index: candidate.index\n          } as GenerateContentCandidate;\n        }\n\n        // Overwrite with the latest metadata\n        aggregatedResponse.candidates[i].citationMetadata =\n          candidate.citationMetadata;\n        aggregatedResponse.candidates[i].finishReason = candidate.finishReason;\n        aggregatedResponse.candidates[i].finishMessage =\n          candidate.finishMessage;\n        aggregatedResponse.candidates[i].safetyRatings =\n          candidate.safetyRatings;\n        aggregatedResponse.candidates[i].groundingMetadata =\n          candidate.groundingMetadata;\n\n        // The urlContextMetadata object is defined in the first chunk of the response stream.\n        // In all subsequent chunks, the urlContextMetadata object will be undefined. We need to\n        // make sure that we don't overwrite the first value urlContextMetadata object with undefined.\n        // FIXME: What happens if we receive a second, valid urlContextMetadata object?\n        const urlContextMetadata = candidate.urlContextMetadata as unknown;\n        if (\n          typeof urlContextMetadata === 'object' &&\n          urlContextMetadata !== null &&\n          Object.keys(urlContextMetadata).length > 0\n        ) {\n          aggregatedResponse.candidates[i].urlContextMetadata =\n            urlContextMetadata as URLContextMetadata;\n        }\n\n        if (candidate.content) {\n          if (!candidate.content.parts) {\n            continue;\n          }\n          if (!aggregatedResponse.candidates[i].content) {\n            aggregatedResponse.candidates[i].content = {\n              role: candidate.content.role || 'user',\n              parts: []\n            };\n          }\n          for (const part of candidate.content.parts) {\n            const newPart: Part = { ...part };\n            // The backend can send empty text parts. If these are sent back\n            // (e.g. in chat history), the backend will respond with an error.\n            // To prevent this, ignore empty text parts.\n            if (part.text === '') {\n              continue;\n            }\n            if (Object.keys(newPart).length > 0) {\n              aggregatedResponse.candidates[i].content.parts.push(\n                newPart as Part\n              );\n            }\n          }\n        }\n      }\n    }\n  }\n  return aggregatedResponse;\n}\n","/**\n * @license\n * Copyright 2025 Google LLC\n *\n * Licensed under the Apache License, Version 2.0 (the \"License\");\n * you may not use this file except in compliance with the License.\n * You may obtain a copy of the License at\n *\n *   http://www.apache.org/licenses/LICENSE-2.0\n *\n * Unless required by applicable law or agreed to in writing, software\n * distributed under the License is distributed on an \"AS IS\" BASIS,\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n * See the License for the specific language governing permissions and\n * limitations under the License.\n */\n\nimport { AIError } from '../errors';\nimport {\n  GenerateContentRequest,\n  InferenceMode,\n  AIErrorCode,\n  ChromeAdapter,\n  InferenceSource\n} from '../types';\n\nconst errorsCausingFallback: AIErrorCode[] = [\n  // most network errors\n  AIErrorCode.FETCH_ERROR,\n  // fallback code for all other errors in makeRequest\n  AIErrorCode.ERROR,\n  // error due to API not being enabled in project\n  AIErrorCode.API_NOT_ENABLED\n];\n\ninterface CallResult<Response> {\n  response: Response;\n  inferenceSource: InferenceSource;\n}\n\n/**\n * Dispatches a request to the appropriate backend (on-device or in-cloud)\n * based on the inference mode.\n *\n * @param request - The request to be sent.\n * @param chromeAdapter - The on-device model adapter.\n * @param onDeviceCall - The function to call for on-device inference.\n * @param inCloudCall - The function to call for in-cloud inference.\n * @returns The response from the backend.\n */\nexport async function callCloudOrDevice<Response>(\n  request: GenerateContentRequest,\n  chromeAdapter: ChromeAdapter | undefined,\n  onDeviceCall: () => Promise<Response>,\n  inCloudCall: () => Promise<Response>\n): Promise<CallResult<Response>> {\n  if (!chromeAdapter) {\n    return {\n      response: await inCloudCall(),\n      inferenceSource: InferenceSource.IN_CLOUD\n    };\n  }\n  switch (chromeAdapter.mode) {\n    case InferenceMode.ONLY_ON_DEVICE:\n      if (await chromeAdapter.isAvailable(request)) {\n        return {\n          response: await onDeviceCall(),\n          inferenceSource: InferenceSource.ON_DEVICE\n        };\n      }\n      throw new AIError(\n        AIErrorCode.UNSUPPORTED,\n        'Inference mode is ONLY_ON_DEVICE, but an on-device model is not available.'\n      );\n    case InferenceMode.ONLY_IN_CLOUD:\n      return {\n        response: await inCloudCall(),\n        inferenceSource: InferenceSource.IN_CLOUD\n      };\n    case InferenceMode.PREFER_IN_CLOUD:\n      try {\n        return {\n          response: await inCloudCall(),\n          inferenceSource: InferenceSource.IN_CLOUD\n        };\n      } catch (e) {\n        if (\n          e instanceof AIError &&\n          errorsCausingFallback.includes(e.code) &&\n          (await chromeAdapter.isAvailable(request))\n        ) {\n          return {\n            response: await onDeviceCall(),\n            inferenceSource: InferenceSource.ON_DEVICE\n          };\n        }\n        throw e;\n      }\n    case InferenceMode.PREFER_ON_DEVICE:\n      if (await chromeAdapter.isAvailable(request)) {\n        return {\n          response: await onDeviceCall(),\n          inferenceSource: InferenceSource.ON_DEVICE\n        };\n      }\n      return {\n        response: await inCloudCall(),\n        inferenceSource: InferenceSource.IN_CLOUD\n      };\n    default:\n      throw new AIError(\n        AIErrorCode.ERROR,\n        `Unexpected infererence mode: ${chromeAdapter.mode}`\n      );\n  }\n}\n","/**\n * @license\n * Copyright 2024 Google LLC\n *\n * Licensed under the Apache License, Version 2.0 (the \"License\");\n * you may not use this file except in compliance with the License.\n * You may obtain a copy of the License at\n *\n *   http://www.apache.org/licenses/LICENSE-2.0\n *\n * Unless required by applicable law or agreed to in writing, software\n * distributed under the License is distributed on an \"AS IS\" BASIS,\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n * See the License for the specific language governing permissions and\n * limitations under the License.\n */\n\nimport {\n  GenerateContentRequest,\n  GenerateContentResponse,\n  GenerateContentResult,\n  GenerateContentStreamResult,\n  SingleRequestOptions\n} from '../types';\nimport {\n  makeRequest,\n  ServerPromptTemplateTask,\n  Task\n} from '../requests/request';\nimport { createEnhancedContentResponse } from '../requests/response-helpers';\nimport { processStream } from '../requests/stream-reader';\nimport { ApiSettings } from '../types/internal';\nimport * as GoogleAIMapper from '../googleai-mappers';\nimport { BackendType, TemplateRequestInternal } from '../public-types';\nimport { ChromeAdapter } from '../types/chrome-adapter';\nimport { callCloudOrDevice } from '../requests/hybrid-helpers';\n\nasync function generateContentStreamOnCloud(\n  apiSettings: ApiSettings,\n  model: string,\n  params: GenerateContentRequest,\n  singleRequestOptions?: SingleRequestOptions\n): Promise<Response> {\n  if (apiSettings.backend.backendType === BackendType.GOOGLE_AI) {\n    params = GoogleAIMapper.mapGenerateContentRequest(params);\n  }\n  return makeRequest(\n    {\n      task: Task.STREAM_GENERATE_CONTENT,\n      model,\n      apiSettings,\n      stream: true,\n      singleRequestOptions\n    },\n    JSON.stringify(params)\n  );\n}\n\nexport async function generateContentStream(\n  apiSettings: ApiSettings,\n  model: string,\n  params: GenerateContentRequest,\n  chromeAdapter?: ChromeAdapter,\n  singleRequestOptions?: SingleRequestOptions\n): Promise<\n  GenerateContentStreamResult & { firstValue?: GenerateContentResponse }\n> {\n  const callResult = await callCloudOrDevice(\n    params,\n    chromeAdapter,\n    () => chromeAdapter!.generateContentStream(params),\n    () =>\n      generateContentStreamOnCloud(\n        apiSettings,\n        model,\n        params,\n        singleRequestOptions\n      )\n  );\n  return processStream(\n    callResult.response,\n    apiSettings,\n    callResult.inferenceSource\n  );\n}\n\nasync function generateContentOnCloud(\n  apiSettings: ApiSettings,\n  model: string,\n  params: GenerateContentRequest,\n  singleRequestOptions?: SingleRequestOptions\n): Promise<Response> {\n  if (apiSettings.backend.backendType === BackendType.GOOGLE_AI) {\n    params = GoogleAIMapper.mapGenerateContentRequest(params);\n  }\n  return makeRequest(\n    {\n      model,\n      task: Task.GENERATE_CONTENT,\n      apiSettings,\n      stream: false,\n      singleRequestOptions\n    },\n    JSON.stringify(params)\n  );\n}\n\nexport async function templateGenerateContent(\n  apiSettings: ApiSettings,\n  templateId: string,\n  templateParams: TemplateRequestInternal,\n  singleRequestOptions?: SingleRequestOptions\n): Promise<GenerateContentResult> {\n  const response = await makeRequest(\n    {\n      task: ServerPromptTemplateTask.TEMPLATE_GENERATE_CONTENT,\n      templateId,\n      apiSettings,\n      stream: false,\n      singleRequestOptions\n    },\n    JSON.stringify(templateParams)\n  );\n  const generateContentResponse = await processGenerateContentResponse(\n    response,\n    apiSettings\n  );\n  const enhancedResponse = createEnhancedContentResponse(\n    generateContentResponse\n  );\n  return {\n    response: enhancedResponse\n  };\n}\n\nexport async function templateGenerateContentStream(\n  apiSettings: ApiSettings,\n  templateId: string,\n  templateParams: TemplateRequestInternal,\n  singleRequestOptions?: SingleRequestOptions\n): Promise<GenerateContentStreamResult> {\n  const response = await makeRequest(\n    {\n      task: ServerPromptTemplateTask.TEMPLATE_STREAM_GENERATE_CONTENT,\n      templateId,\n      apiSettings,\n      stream: true,\n      singleRequestOptions\n    },\n    JSON.stringify(templateParams)\n  );\n  return processStream(response, apiSettings);\n}\n\nexport async function generateContent(\n  apiSettings: ApiSettings,\n  model: string,\n  params: GenerateContentRequest,\n  chromeAdapter?: ChromeAdapter,\n  singleRequestOptions?: SingleRequestOptions\n): Promise<GenerateContentResult> {\n  const callResult = await callCloudOrDevice(\n    params,\n    chromeAdapter,\n    () => chromeAdapter!.generateContent(params),\n    () =>\n      generateContentOnCloud(apiSettings, model, params, singleRequestOptions)\n  );\n  const generateContentResponse = await processGenerateContentResponse(\n    callResult.response,\n    apiSettings\n  );\n  const enhancedResponse = createEnhancedContentResponse(\n    generateContentResponse,\n    callResult.inferenceSource\n  );\n  return {\n    response: enhancedResponse\n  };\n}\n\nasync function processGenerateContentResponse(\n  response: Response,\n  apiSettings: ApiSettings\n): Promise<GenerateContentResponse> {\n  const responseJson = await response.json();\n  if (apiSettings.backend.backendType === BackendType.GOOGLE_AI) {\n    return GoogleAIMapper.mapGenerateContentResponse(responseJson);\n  } else {\n    return responseJson;\n  }\n}\n","/**\n * @license\n * Copyright 2024 Google LLC\n *\n * Licensed under the Apache License, Version 2.0 (the \"License\");\n * you may not use this file except in compliance with the License.\n * You may obtain a copy of the License at\n *\n *   http://www.apache.org/licenses/LICENSE-2.0\n *\n * Unless required by applicable law or agreed to in writing, software\n * distributed under the License is distributed on an \"AS IS\" BASIS,\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n * See the License for the specific language governing permissions and\n * limitations under the License.\n */\n\nimport { Content, GenerateContentRequest, Part, AIErrorCode } from '../types';\nimport { AIError } from '../errors';\n\nexport function formatSystemInstruction(\n  input?: string | Part | Content\n): Content | undefined {\n  // null or undefined\n  if (input == null) {\n    return undefined;\n  } else if (typeof input === 'string') {\n    return { role: 'system', parts: [{ text: input }] } as Content;\n  } else if ((input as Part).text) {\n    return { role: 'system', parts: [input as Part] };\n  } else if ((input as Content).parts) {\n    if (!(input as Content).role) {\n      return { role: 'system', parts: (input as Content).parts };\n    } else {\n      return input as Content;\n    }\n  }\n}\n\nexport function formatNewContent(\n  request: string | Array<string | Part>\n): Content {\n  let newParts: Part[] = [];\n  if (typeof request === 'string') {\n    newParts = [{ text: request }];\n  } else {\n    for (const partOrString of request) {\n      if (typeof partOrString === 'string') {\n        newParts.push({ text: partOrString });\n      } else {\n        newParts.push(partOrString);\n      }\n    }\n  }\n  return assignRoleToPartsAndValidateSendMessageRequest(newParts);\n}\n\n/**\n * Validates the parts of a message to ensure that FunctionResponseParts\n * are not mixed with other part types in a single request.\n * All parts are now assigned the 'user' role to comply with 3.6+ model requirements.\n * @private\n * @param parts Array of parts to pass to the model\n * @returns A single Content item formatted for the model\n */\nfunction assignRoleToPartsAndValidateSendMessageRequest(\n  parts: Part[]\n): Content {\n  const content: Content = { role: 'user', parts: [] };\n  let hasUserContent = false;\n  let hasFunctionContent = false;\n  for (const part of parts) {\n    if ('functionResponse' in part) {\n      hasFunctionContent = true;\n    } else {\n      hasUserContent = true;\n    }\n    content.parts.push(part);\n  }\n\n  if (hasUserContent && hasFunctionContent) {\n    throw new AIError(\n      AIErrorCode.INVALID_CONTENT,\n      'Within a single message, FunctionResponse cannot be mixed with other type of Part in the request for sending chat message.'\n    );\n  }\n\n  if (!hasUserContent && !hasFunctionContent) {\n    throw new AIError(\n      AIErrorCode.INVALID_CONTENT,\n      'No Content is provided for sending chat message.'\n    );\n  }\n\n  return content;\n}\n\nexport function formatGenerateContentInput(\n  params: GenerateContentRequest | string | Array<string | Part>\n): GenerateContentRequest {\n  let formattedRequest: GenerateContentRequest;\n  if ((params as GenerateContentRequest).contents) {\n    formattedRequest = params as GenerateContentRequest;\n  } else {\n    // Array or string\n    const content = formatNewContent(params as string | Array<string | Part>);\n    formattedRequest = { contents: [content] };\n  }\n  if ((params as GenerateContentRequest).systemInstruction) {\n    formattedRequest.systemInstruction = formatSystemInstruction(\n      (params as GenerateContentRequest).systemInstruction\n    );\n  }\n  return formattedRequest;\n}\n","/**\n * @license\n * Copyright 2026 Google LLC\n *\n * Licensed under the Apache License, Version 2.0 (the \"License\");\n * you may not use this file except in compliance with the License.\n * You may obtain a copy of the License at\n *\n *   http://www.apache.org/licenses/LICENSE-2.0\n *\n * Unless required by applicable law or agreed to in writing, software\n * distributed under the License is distributed on an \"AS IS\" BASIS,\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n * See the License for the specific language governing permissions and\n * limitations under the License.\n */\n\nimport {\n  AIErrorCode,\n  Content,\n  FunctionCall,\n  FunctionDeclarationsTool,\n  FunctionResponse,\n  FunctionResponsePart,\n  GenerateContentResponse,\n  GenerateContentResult,\n  GenerateContentStreamResult,\n  Part,\n  RequestOptions,\n  SingleRequestOptions,\n  StartChatParams,\n  StartTemplateChatParams,\n  TemplateFunctionDeclarationsTool\n} from '../types';\nimport { formatNewContent } from '../requests/request-helpers';\nimport {\n  formatBlockErrorMessage,\n  getFunctionCalls\n} from '../requests/response-helpers';\nimport { ApiSettings } from '../types/internal';\nimport { logger } from '../logger';\nimport { AIError } from '../errors';\n\n/**\n * Used to break the internal promise chain when an error is already handled\n * by the user, preventing duplicate console logs.\n */\nconst SILENT_ERROR = 'SILENT_ERROR';\n\n/**\n * Prevent infinite loop if the model continues to request sequential\n * function calls during automatic function calling.\n */\nconst DEFAULT_MAX_SEQUENTIAL_FUNCTION_CALLS = 10;\n\n/**\n * Base class for various `ChatSession` classes that enables sending chat\n * messages and stores history of sent and received messages so far.\n *\n * @public\n */\nexport abstract class ChatSessionBase<\n  ParamsType extends StartChatParams | StartTemplateChatParams,\n  RequestType,\n  FunctionDeclarationsToolType extends\n    FunctionDeclarationsTool | TemplateFunctionDeclarationsTool\n> {\n  protected _apiSettings: ApiSettings;\n  protected _history: Content[] = [];\n\n  /**\n   * Ensures sequential execution of chat messages to maintain history order.\n   * Each call waits for the previous one to settle before proceeding.\n   * @internal\n   */\n  protected _sendPromise: Promise<void> = Promise.resolve();\n\n  constructor(\n    apiSettings: ApiSettings,\n    public params?: ParamsType,\n    public requestOptions?: RequestOptions\n  ) {\n    this._apiSettings = apiSettings;\n  }\n\n  /**\n   * Gets the chat history so far. Blocked prompts are not added to history.\n   * Neither blocked candidates nor the prompts that generated them are added\n   * to history.\n   */\n  async getHistory(): Promise<Content[]> {\n    await this._sendPromise;\n    return this._history;\n  }\n\n  /**\n   * Format Content into a request for `generateContent` or\n   * `generateContentStream` (or their template versions).\n   * @internal\n   */\n  abstract _formatRequest(\n    incomingContent: Content,\n    tempHistory: Content[]\n  ): RequestType;\n\n  /**\n   * Type-specific generate content calls (inherited classes may implement this\n   * to call basic `generateContent()` or the template version)\n   * @internal\n   */\n  abstract _callGenerateContent(\n    formattedRequest: RequestType,\n    singleRequestOptions?: RequestOptions\n  ): Promise<GenerateContentResult>;\n\n  /**\n   * Type-specific generate content stream calls (inherited classes may implement this\n   * to call basic `generateContentStream()` or the template version)\n   * @internal\n   */\n  abstract _callGenerateContentStream(\n    formattedRequest: RequestType,\n    singleRequestOptions?: RequestOptions\n  ): Promise<GenerateContentStreamResult>;\n\n  /**\n   * Sends a chat message and receives a non-streaming\n   * {@link GenerateContentResult}\n   * @internal\n   */\n  async _sendMessage(\n    request: string | Array<string | Part>,\n    singleRequestOptions?: SingleRequestOptions\n  ): Promise<GenerateContentResult> {\n    let finalResult = {} as GenerateContentResult;\n    await this._sendPromise;\n    /**\n     * Temporarily store multiple turns for cases like automatic function\n     * calling, only writing them to official history when the entire\n     * sequence has completed successfully.\n     */\n    const tempHistory: Content[] = [];\n\n    this._sendPromise = this._sendPromise.then(async () => {\n      let functionCalls: FunctionCall[] | undefined;\n      let functionCallTurnCount = 0;\n      const functionCallMaxTurns =\n        this.requestOptions?.maxSequentialFunctionCalls ??\n        DEFAULT_MAX_SEQUENTIAL_FUNCTION_CALLS;\n\n      // Repeats until model returns a response with no function calls\n      // or until `functionCallMaxTurns` is met or exceeded.\n      do {\n        let formattedContent;\n\n        if (functionCalls) {\n          functionCallTurnCount++;\n          const functionResponseParts =\n            await this._callFunctionsAsNeeded(functionCalls);\n          formattedContent = formatNewContent(functionResponseParts);\n        } else {\n          formattedContent = formatNewContent(request);\n        }\n        const formattedRequest = this._formatRequest(formattedContent, [\n          ...tempHistory\n        ]);\n\n        tempHistory.push(formattedContent);\n\n        const result = await this._callGenerateContent(\n          formattedRequest,\n          singleRequestOptions\n        );\n        if (result) {\n          finalResult = result;\n          functionCalls = this._getCallableFunctionCalls(result.response);\n          if (\n            result.response.candidates &&\n            result.response.candidates.length > 0\n          ) {\n            // TODO: Make this update atomic. If creating `responseContent` throws,\n            // history will contain the user message but not the response, causing\n            // validation errors on the next request.\n            const responseContent: Content = {\n              parts: result.response.candidates?.[0].content.parts || [],\n              // Response seems to come back without a role set.\n              role: result.response.candidates?.[0].content.role || 'model'\n            };\n            tempHistory.push(responseContent);\n          } else {\n            const blockErrorMessage = formatBlockErrorMessage(result.response);\n            if (blockErrorMessage) {\n              logger.warn(\n                `sendMessage() was unsuccessful. ${blockErrorMessage}. Inspect response object for details.`\n              );\n            }\n          }\n        } else {\n          functionCalls = undefined;\n        }\n      } while (functionCalls && functionCallTurnCount < functionCallMaxTurns);\n\n      if (functionCalls && functionCallTurnCount >= functionCallMaxTurns) {\n        logger.warn(\n          